<?php
if(!defined('ABSPATH'))exit;
function dgs_register_content(){
    register_post_type('dgs_teacher',array('labels'=>array('name'=>'اساتید و کادر مدرسه','singular_name'=>'عضو کادر','add_new_item'=>'افزودن عضو کادر','edit_item'=>'ویرایش عضو کادر'),'public'=>true,'has_archive'=>false,'show_in_rest'=>true,'rewrite'=>array('slug'=>'teacher'),'supports'=>array('title','editor','thumbnail','excerpt'),'menu_icon'=>'dashicons-welcome-learn-more','show_in_menu'=>'dgs-setup','capabilities'=>array('create_posts'=>'manage_options','edit_posts'=>'manage_options','edit_others_posts'=>'manage_options','publish_posts'=>'manage_options','delete_posts'=>'manage_options','delete_others_posts'=>'manage_options','read_private_posts'=>'manage_options'),'map_meta_cap'=>true));
    register_post_type('dgs_class',array('labels'=>array('name'=>'کلاس‌های تقویتی','singular_name'=>'کلاس تقویتی','add_new_item'=>'افزودن کلاس تقویتی'),'public'=>true,'has_archive'=>false,'show_in_rest'=>true,'rewrite'=>array('slug'=>'academy-class'),'supports'=>array('title','editor','thumbnail','excerpt'),'menu_icon'=>'dashicons-calendar-alt','show_in_menu'=>'dgs-setup','capabilities'=>array('create_posts'=>'manage_options','edit_posts'=>'manage_options','edit_others_posts'=>'manage_options','publish_posts'=>'manage_options','delete_posts'=>'manage_options','delete_others_posts'=>'manage_options','read_private_posts'=>'manage_options'),'map_meta_cap'=>true));
    register_post_type('dgs_star',array('labels'=>array('name'=>'دانش‌آموزان برگزیده','singular_name'=>'دانش‌آموز برگزیده'),'public'=>false,'show_ui'=>true,'show_in_menu'=>'dgs-setup','supports'=>array('title','editor','thumbnail'),'capabilities'=>array('create_posts'=>'manage_options','edit_posts'=>'manage_options','edit_others_posts'=>'manage_options','publish_posts'=>'manage_options','delete_posts'=>'manage_options','read_private_posts'=>'manage_options'),'map_meta_cap'=>true));
    register_post_type('dgs_request',array('labels'=>array('name'=>'درخواست‌های دریافتی','singular_name'=>'درخواست','edit_item'=>'بررسی درخواست'),'public'=>false,'publicly_queryable'=>false,'exclude_from_search'=>true,'show_in_rest'=>false,'show_ui'=>true,'show_in_menu'=>'dgs-setup','supports'=>array('title'),'capability_type'=>array('dgs_request','dgs_requests'),'map_meta_cap'=>true,'capabilities'=>array('create_posts'=>'do_not_allow')));
}
add_action('init','dgs_register_content');
function dgs_meta_fields($type){
    if($type==='dgs_teacher')return array('_dgs_specialty'=>'درس یا سمت','_dgs_group'=>'گروه نمایش: teacher برای اساتید، staff برای مدیریت و کادر','_dgs_video'=>'آدرس مستقیم فیلم معرفی (MP4)');
    if($type==='dgs_class')return array('_dgs_teacher_user'=>'دبیر مرتبط (اتصال به رزومه حساب)','_dgs_subject'=>'نام درس / موضوع کلاس','_dgs_days'=>'روزهای برگزاری: شنبه=0 تا پنجشنبه=5، مانند 0,2','_dgs_time_start'=>'ساعت شروع مانند 16:00','_dgs_time_end'=>'ساعت پایان مانند 17:30','_dgs_venue'=>'محل برگزاری','_dgs_start_date'=>'تاریخ شروع (شمسی)','_dgs_schedule'=>'روز و ساعت برگزاری','_dgs_teacher_name'=>'نام مدرس','_dgs_grade'=>'پایه تحصیلی','_dgs_capacity'=>'ظرفیت کلاس (عدد)');
    if($type==='dgs_star')return array('_dgs_period'=>'بازه: week / month / term / year','_dgs_star_class'=>'پایه و رشته','_dgs_achievement'=>'عنوان موفقیت');
    return array();
}
add_action('add_meta_boxes',function(){foreach(array('dgs_teacher','dgs_class','dgs_star') as $type)add_meta_box('dgs_details','اطلاعات تکمیلی دانشگران','dgs_meta_box',$type,'normal','high');add_meta_box('dgs_request_details','جزئیات درخواست','dgs_request_meta_box','dgs_request','normal','high');});
function dgs_meta_box($post){wp_nonce_field('dgs_meta','dgs_meta_nonce');echo '<p>عنوان، متن معرفی و تصویر شاخص را از بخش‌های اصلی همین صفحه وارد کنید.</p><table class="form-table">';foreach(dgs_meta_fields($post->post_type) as $key=>$label){$val=get_post_meta($post->ID,$key,true);if($key==='_dgs_group'&&!$val)$val='teacher';if($key==='_dgs_period'&&!$val)$val='month';if($key==='_dgs_teacher_user'){echo '<tr><th>'.esc_html($label).'</th><td><select name="_dgs_teacher_user"><option value="">انتخاب دبیر</option>';foreach(get_users(array('role'=>'dgs_teacher','number'=>1000,'orderby'=>'display_name','order'=>'ASC')) as $teacher)echo '<option value="'.(int)$teacher->ID.'" '.selected($val,(string)$teacher->ID,false).'>'.esc_html($teacher->display_name).'</option>';echo '</select></td></tr>';continue;}echo '<tr><th><label for="'.esc_attr($key).'">'.esc_html($label).'</label></th><td><input class="regular-text" id="'.esc_attr($key).'" name="'.esc_attr($key).'" value="'.esc_attr($val).'" dir="'.(in_array($key,array('_dgs_group','_dgs_period','_dgs_video'),true)?'ltr':'rtl').'"></td></tr>';}echo '</table>';}
add_action('save_post',function($id,$post){
    if(!isset($_POST['dgs_meta_nonce'])||!is_string($_POST['dgs_meta_nonce'])||!wp_verify_nonce(wp_unslash($_POST['dgs_meta_nonce']),'dgs_meta')||!current_user_can('manage_options')||wp_is_post_revision($id)||(defined('DOING_AUTOSAVE')&&DOING_AUTOSAVE))return;
    foreach(dgs_meta_fields($post->post_type) as $key=>$label){if(!isset($_POST[$key])||!is_string($_POST[$key]))continue;$v=wp_unslash($_POST[$key]);
        if($key==='_dgs_video')$v=esc_url_raw($v,array('http','https'));elseif($key==='_dgs_capacity')$v=(string)absint($v);elseif($key==='_dgs_group')$v=in_array($v,array('teacher','staff'),true)?$v:'teacher';elseif($key==='_dgs_period')$v=in_array($v,array('week','month','term','year'),true)?$v:'month';else $v=sanitize_text_field($v);update_post_meta($id,$key,$v);
    }
},10,2);
function dgs_request_meta_box($post){
    if(!current_user_can('read_post',$post->ID))return;
    $data=get_post_meta($post->ID,'_dgs_data',true);$data=is_array($data)?$data:array();
    $labels=array('type'=>'نوع درخواست','name'=>'نام دانش‌آموز / متقاضی','phone'=>'تلفن تماس','grade'=>'پایه','field'=>'رشته','parent_name'=>'نام ولی','email'=>'ایمیل','message'=>'توضیحات','class_id'=>'کلاس تقویتی','created'=>'زمان ثبت');
    echo '<table class="widefat striped">';foreach($labels as $key=>$label){$v=$data[$key]??'';if($key==='class_id'&&$v)$v=get_the_title((int)$v).' ('.(int)$v.')';if($key==='type')$v=dgs_request_types()[$v]??$v;echo '<tr><th>'.esc_html($label).'</th><td style="white-space:pre-wrap">'.esc_html((string)$v).'</td></tr>';}echo '</table>';
    wp_nonce_field('dgs_request_review','dgs_review_nonce');$status=get_post_meta($post->ID,'_dgs_status',true)?:'new';echo '<p><label>وضعیت پیگیری <select name="dgs_status">';foreach(dgs_request_states() as $key=>$label)echo '<option value="'.esc_attr($key).'" '.selected($status,$key,false).'>'.esc_html($label).'</option>';echo '</select></label></p><label>یادداشت داخلی مدیریت<textarea name="dgs_staff_note" style="width:100%;min-height:100px">'.esc_textarea(get_post_meta($post->ID,'_dgs_staff_note',true)).'</textarea></label>';
}
add_action('save_post_dgs_request',function($id){if(!isset($_POST['dgs_review_nonce'])||!is_string($_POST['dgs_review_nonce'])||!wp_verify_nonce(wp_unslash($_POST['dgs_review_nonce']),'dgs_request_review')||!current_user_can('edit_post',$id)||wp_is_post_revision($id))return;
    $status=isset($_POST['dgs_status'])&&is_string($_POST['dgs_status'])?sanitize_key($_POST['dgs_status']):'';if(in_array($status,array_keys(dgs_request_states()),true))update_post_meta($id,'_dgs_status',$status);
    if(isset($_POST['dgs_staff_note'])&&is_string($_POST['dgs_staff_note']))update_post_meta($id,'_dgs_staff_note',sanitize_textarea_field(wp_unslash($_POST['dgs_staff_note'])));
});
add_filter('manage_dgs_request_posts_columns',function($cols){return array('cb'=>$cols['cb'],'title'=>'درخواست','dgs_type'=>'نوع','dgs_status'=>'پیگیری','date'=>'زمان');});
add_action('manage_dgs_request_posts_custom_column',function($col,$id){if($col==='dgs_type'){$d=get_post_meta($id,'_dgs_data',true);echo esc_html(dgs_request_types()[$d['type']??'']??'');}if($col==='dgs_status')echo esc_html(dgs_request_states()[get_post_meta($id,'_dgs_status',true)?:'new']??'');},10,2);
